//! `execute shim PROGRAM`: writes a generated Bash stub that runs PROGRAM through
//! `execute run`, so callers that run files with `bash FILE` or match `*.sh` keep working.

use anyhow::{bail, Context, Result};
use std::fs;
use std::io::{self, Write};
use std::path::{Path, PathBuf};

const SHEBANG: &str = "#!/usr/bin/env bash";
const GENERATED_COMMENT: &str =
    "# Generated by `execute shim`. Do not edit; regenerate it instead.";
const USAGE: &str = "Usage: execute shim PROGRAM [--name NAME] [--out DIR] [--force]";

/// The stub text for an absolute program path. The path is written as one single-quoted
/// Bash word, so no character in it is ever interpreted by the shell.
pub(crate) fn stub_text(program: &Path) -> Result<String> {
    if !program.is_absolute() {
        bail!(
            "the stub needs an absolute program path, got {}",
            program.display()
        );
    }
    let text = program
        .to_str()
        .context("the program path must be valid UTF-8 to be written into a stub")?;
    if text.contains(['\n', '\r', '\0']) {
        bail!("refusing to write a stub for a program path with a newline or NUL: {text:?}");
    }
    Ok(format!(
        "{SHEBANG}\n{GENERATED_COMMENT}\nexec execute run {} -- \"$@\"\n",
        single_quote(text)
    ))
}

/// Quote `text` for Bash: wrap it in single quotes, and close, escape and reopen the
/// quotes around every single quote inside it.
fn single_quote(text: &str) -> String {
    let mut quoted = String::with_capacity(text.len() + 2);
    quoted.push('\'');
    for character in text.chars() {
        if character == '\'' {
            quoted.push_str("'\\''");
        } else {
            quoted.push(character);
        }
    }
    quoted.push('\'');
    quoted
}

/// Create `target` with `text` as its new contents. An existing file is refused unless
/// `force` is set, in which case it is removed first (a symlink is replaced, not followed).
/// On Unix the stub is made executable, 0755, whatever the umask says.
pub(crate) fn write_stub(target: &Path, text: &[u8], force: bool) -> Result<()> {
    if force {
        match fs::remove_file(target) {
            Ok(()) => {}
            Err(error) if error.kind() == io::ErrorKind::NotFound => {}
            Err(error) => {
                return Err(error).with_context(|| format!("replacing {}", target.display()));
            }
        }
    }
    let mut file = fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(target)
        .map_err(|error| {
            if error.kind() == io::ErrorKind::AlreadyExists {
                anyhow::anyhow!(
                    "{} already exists; pass --force to replace it",
                    target.display()
                )
            } else {
                anyhow::Error::new(error).context(format!("creating {}", target.display()))
            }
        })?;
    file.write_all(text)
        .with_context(|| format!("writing {}", target.display()))?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        file.set_permissions(fs::Permissions::from_mode(0o755))
            .with_context(|| format!("making {} executable", target.display()))?;
    }
    Ok(())
}

/// The default stub file name: the program's file stem with a `.sh` extension.
fn default_name(program: &Path) -> Result<String> {
    let stem = program
        .file_stem()
        .and_then(|stem| stem.to_str())
        .filter(|stem| !stem.is_empty())
        .context("the program has no usable file name; pass --name")?;
    Ok(format!("{stem}.sh"))
}

/// A stub file name must be one plain path component.
fn checked_name(name: &str) -> Result<&str> {
    let plain = !name.is_empty()
        && name != "."
        && name != ".."
        && !name.contains(['/', '\\', '\n', '\r', '\0']);
    if !plain {
        bail!("--name must be a single file name, got {name:?}");
    }
    Ok(name)
}

/// `execute shim PROGRAM [--name NAME] [--out DIR] [--force]`.
pub(crate) fn cli(arguments: &[String]) -> Result<()> {
    let mut program: Option<PathBuf> = None;
    let mut name: Option<String> = None;
    let mut out: Option<PathBuf> = None;
    let mut force = false;
    let mut index = 0;
    while index < arguments.len() {
        let argument = arguments[index].as_str();
        match argument {
            "--help" | "-h" => {
                writeln!(io::stdout(), "{USAGE}")?;
                return Ok(());
            }
            "--force" => force = true,
            "--name" | "--out" => {
                index += 1;
                let value = arguments
                    .get(index)
                    .with_context(|| format!("{argument} requires a value\n{USAGE}"))?;
                if argument == "--name" {
                    name = Some(value.clone());
                } else {
                    out = Some(PathBuf::from(value));
                }
            }
            _ if argument.starts_with("--") => {
                bail!("unknown shim option {argument}\n{USAGE}");
            }
            _ => {
                if program.is_some() {
                    bail!("shim takes one program\n{USAGE}");
                }
                program = Some(PathBuf::from(argument));
            }
        }
        index += 1;
    }
    let program = program.with_context(|| format!("a program path is required\n{USAGE}"))?;
    let program = std::path::absolute(&program)
        .with_context(|| format!("resolving {}", program.display()))?;
    if !program.is_file() {
        bail!("{} is not a file", program.display());
    }
    let text = stub_text(&program)?;
    let file_name = match name {
        Some(name) => checked_name(&name)?.to_owned(),
        None => default_name(&program)?,
    };
    let target = out.unwrap_or_else(|| PathBuf::from(".")).join(file_name);
    write_stub(&target, text.as_bytes(), force)?;
    writeln!(io::stdout(), "wrote {}", target.display())?;
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn root() -> PathBuf {
        PathBuf::from(if cfg!(windows) { r"C:\work" } else { "/work" })
    }

    #[test]
    fn stub_text_for_an_ordinary_path_is_exact() {
        let program = root().join("hook.program");
        let expected = format!(
            "#!/usr/bin/env bash\n{GENERATED_COMMENT}\nexec execute run '{}' -- \"$@\"\n",
            program.display()
        );
        assert_eq!(stub_text(&program).unwrap(), expected);
    }

    #[test]
    fn stub_text_quotes_spaces_quotes_dollars_and_backticks_literally() {
        let program = root().join("it's a $HOME `x` \"q\".program");
        let text = stub_text(&program).unwrap();
        let quoted = format!("'{}'", program.display().to_string().replace('\'', "'\\''"));
        assert_eq!(
            text.lines().nth(2),
            Some(format!("exec execute run {quoted} -- \"$@\"").as_str())
        );
        assert_eq!(text.lines().count(), 3);
    }

    #[test]
    fn stub_text_refuses_newline_and_nul_paths() {
        assert!(stub_text(&root().join("a\nb.program")).is_err());
        assert!(stub_text(&root().join("a\rb.program")).is_err());
        assert!(stub_text(&root().join("a\0b.program")).is_err());
    }

    #[test]
    fn stub_text_refuses_a_relative_path() {
        assert!(stub_text(Path::new("hook.program")).is_err());
    }

    #[test]
    fn write_stub_refuses_to_overwrite_unless_forced() {
        let dir = tempfile::tempdir().unwrap();
        let target = dir.path().join("theme-set.sh");
        write_stub(&target, b"first\n", false).unwrap();
        let refused = write_stub(&target, b"second\n", false).unwrap_err();
        assert!(refused.to_string().contains("--force"), "{refused}");
        assert_eq!(fs::read(&target).unwrap(), b"first\n");
        write_stub(&target, b"second\n", true).unwrap();
        assert_eq!(fs::read(&target).unwrap(), b"second\n");
    }

    #[test]
    fn checked_name_accepts_one_plain_component_only() {
        assert!(checked_name("theme-set.sh").is_ok());
        assert!(checked_name("").is_err());
        assert!(checked_name(".").is_err());
        assert!(checked_name("..").is_err());
        assert!(checked_name("a/b.sh").is_err());
        assert!(checked_name("a\\b.sh").is_err());
    }
}
